<div class="section-head"><div><h2>My submissions</h2><p class="muted">Track every queued and judged solution.</p></div><a class="button" href="<?=e(url('/contests'))?>">Browse contests</a></div><div class="table-wrap"><table class="data-table"><thead><tr><th>ID</th><th>Contest / Problem</th><th>Language</th><th>Verdict</th><th>Time</th><th>Memory</th><th>Submitted</th></tr></thead><tbody><?php foreach($submissions as $s):?><tr><td><a href="<?=e(url('/submissions/'.$s['submission_id']))?>">#<?=e($s['submission_id'])?></a></td><td><?=e($s['contest_title'])?><br><strong><?=e($s['problem_code'].'. '.$s['problem_title'])?></strong></td><td><?=e($s['language'])?></td><td><span class="badge badge-<?=e(strtolower($s['verdict']))?>"><?=e(str_replace('_',' ',$s['verdict']))?></span></td><td><?=e($s['execution_time_ms']??'—')?> ms</td><td><?=e($s['memory_used_kb']??'—')?> KB</td><td><?=e($s['submitted_at'])?></td></tr><?php endforeach;?><?php if(!$submissions):?><tr><td colspan="7" class="empty">No submissions yet.</td></tr><?php endif;?></tbody></table></div>
